{"file_path":"test/hc-06-ambiguous-rollback.test.ts","content":"import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import test from 'node:test';
import { temporaryDatabase, removeTemporaryDatabase, legacyDatabase, input, entry, consolidate, logicalState } from './hard-case-helpers.mjs';

test('AC-007-03: fingerprint collision and seller-link conflict roll back the batch', () => {
  const ambiguous = temporaryDatabase();
  const conflict = temporaryDatabase();
  try {
    legacyDatabase(ambiguous.database, [{ name: 'Model X', brand: 'Acme', category: 'Electronics' }]);
    consolidate(ambiguous.database, input([entry()]));
    const db = new DatabaseSync(ambiguous.database);
    db.exec('DROP INDEX sqlite_autoindex_ProductIdentity_1');
    db.prepare('INSERT INTO Product (Name, Brand, Category) VALUES (?, ?, ?)').run('model x', 'acme', 'electronics');
    db.close();
    const beforeAmbiguous = logicalState(ambiguous.database);
    assert.throws(() => consolidate(ambiguous.database, input([entry({ Id: 'other' })])), /Identity resolution found/);
    assert.deepEqual(logicalState(ambiguous.database), beforeAmbiguous);

    legacyDatabase(conflict.database);
    consolidate(conflict.database, input([entry()]));
    const conflictDb = new DatabaseSync(conflict.database);
    conflictDb.prepare('INSERT INTO Product (Name, Brand, Category) VALUES (?, ?, ?)').run('Different', 'Acme', 'Electronics');
    const differentId = conflictDb.prepare('SELECT max(Id) AS id FROM Product').get().id;
    conflictDb.prepare('INSERT INTO ProductIdentity (ProductId, CanonicalVersion, CanonicalName, CanonicalBrand, CanonicalCategory, Fingerprint) VALUES (?, ?, ?, ?, ?, ?)').run(differentId, 1, 'different', 'acme', 'electronics', 'v1\u0000different\u0000acme\u0000electronics');
    conflictDb.prepare('UPDATE SellerProduct SET ProductId = ?').run(differentId);
    conflictDb.close();
    const beforeConflict = logicalState(conflict.database);
    assert.throws(() => consolidate(conflict.database, input([entry()])), /Seller link conflict/);
    assert.deepEqual(logicalState(conflict.database), beforeConflict);
  } finally { removeTemporaryDatabase(ambiguous); removeTemporaryDatabase(conflict); }
});
"}

{"file_path":"test/hc-07-rerun-order.test.ts","content":"import assert from 'node:assert/strict';
import test from 'node:test';
import { temporaryDatabase, removeTemporaryDatabase, legacyDatabase, input, entry, consolidate, logicalState } from './hard-case-helpers.mjs';

test('AC-007-02: reruns insert nothing and permutations yield identical logical state', () => {
  const first = temporaryDatabase();
  const second = temporaryDatabase();
  const rows = [entry({ Id: '1', Name: 'Model One' }), entry({ Id: '2', SellerName: 'Seller B', Name: 'Model Two' })];
  try {
    legacyDatabase(first.database); legacyDatabase(second.database);
    consolidate(first.database, input(rows));
    const rerun = consolidate(first.database, input(rows));
    assert.deepEqual([rerun.insertedProducts, rerun.insertedLinks], [0, 0]);
    consolidate(second.database, input([...rows].reverse()));
    assert.deepEqual(logicalState(first.database), logicalState(second.database));
  } finally { removeTemporaryDatabase(first); removeTemporaryDatabase(second); }
});
"}

{"file_path":"test/hc-08-hostile-text.test.ts","content":"import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import test from 'node:test';
import { temporaryDatabase, removeTemporaryDatabase, legacyDatabase, input, entry, consolidate } from './hard-case-helpers.mjs';

test('AC-007-03: hostile strings remain data and schema plus foreign keys stay intact', () => {
  const fixture = temporaryDatabase();
  const hostile = `name'; DROP TABLE Product; -- \\u001b[31m`;
  try {
    legacyDatabase(fixture.database);
    consolidate(fixture.database, input([entry({ Id: hostile, SellerName: hostile, Name: hostile, Brand: hostile, Category: hostile })]));
    const database = new DatabaseSync(fixture.database, { readOnly: true });
    assert.equal(database.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'Product'").get().name, 'Product');
    assert.equal(database.prepare('SELECT Name FROM Product').get().Name, hostile);
    assert.deepEqual(database.prepare('PRAGMA foreign_key_check').all(), []);
    database.close();
  } finally { removeTemporaryDatabase(fixture); }
});
"}

